namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and communication." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and has published over 40 papers in top-tier conferences.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 310", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, transaction processing, and distributed databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked at Oracle for a decade before joining academia. Her research focuses on query optimization.", IsFeatured = false },
            new() { Id = 4, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator who has taught calculus for over 20 years.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Elena Petrov", InstructorBio = "Dr. Petrov's research spans abstract algebra and its applications in cryptography.", IsFeatured = false },
            new() { Id = 6, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "ENG 101", Title = "College Writing", Description = "Develop clear, effective writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Wright", InstructorBio = "Prof. Wright is a published author and has mentored hundreds of students in academic writing.", IsFeatured = false },
            new() { Id = 7, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, examining themes of identity and culture.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Angela Morrison", InstructorBio = "Dr. Morrison specializes in 20th-century American fiction and has published two books on the Harlem Renaissance.", IsFeatured = true },
            new() { Id = 8, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster's research in experimental physics has been funded by NSF for over a decade.", IsFeatured = false },
            new() { Id = 9, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "PHYS 220", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, and applications to atomic systems.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma is a theoretical physicist whose work on quantum computing has been featured in Nature.", IsFeatured = true },
            new() { Id = 10, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "HIST 101", Title = "World History to 1500", Description = "A global survey of human civilizations from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is an archaeologist and historian who has led excavations across the Mediterranean.", IsFeatured = false },
            new() { Id = 11, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "HIST 305", Title = "Modern European History", Description = "Europe from the French Revolution to the present: political revolutions, industrialization, and world wars.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Claire Dumont", InstructorBio = "Dr. Dumont studied at the Sorbonne and specializes in Franco-German relations.", IsFeatured = false },
            new() { Id = 12, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, and practical applications using Python and TensorFlow.", Credits = 3, Schedule = "Mon/Wed 4:00–5:20 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT.", IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public Department? GetDepartmentByCode(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? search = null, string? departmentCode = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.DepartmentCode).ThenBy(c => c.CourseNumber).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).OrderBy(c => c.CourseNumber).ToList();
}

